import{Module}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{THREE,materials}from'./geometry.js';import data from'./geometry-data.js';import{spec}from'./dimensions.js';
function build(host,kind){const frame=new THREE.Group();frame.name='TimerCamera-F actual static '+kind+' mating frame';frame.rotation.x=Math.PI/2;frame.position.y=-10;host.body.add(frame);const saved=host.body;host.body=frame;let parts;try{parts=addCadParts(host,data.filter(x=>x.role===kind),{shell:materials.plastic(0x343833,{roughness:.82})});}finally{host.body=saved;}host.timerCameraFAccessory={kind,frame,parts,nativeMesh:Object.values(parts)[0]};}
export class Clip extends Module{static meta={id:'m5stack.unit.timercamera-f.clip',name:'TimerCamera-F supplied static retaining clip',sku:'U082-F accessory',connector:spec.mount.connector};build(){build(this,'clip');}}
export class Wall1515 extends Module{static meta={id:'m5stack.unit.timercamera-f.wall1515',name:'TimerCamera-F supplied static Wall1515 adapter',sku:'U082-F accessory',connector:spec.mount.connector};build(){build(this,'adapter');}}
